        curses.curs_set(0)
        curses.start_color()
        curses.use_default_colors()
        curses.init_pair(1, curses.COLOR_RED, -1) # Today
        curses.init_pair(2, curses.COLOR_BLUE, -1) # Weekend
        curses.init_pair(3, curses.COLOR_GREEN, -1) # Event

        focus = 0 # 0:Sections, 1:Tags, 2:Calendar
        sel_sec = 0
        sel_tag = 0

        while True:
            stdscr.clear()
            height, width = stdscr.getmaxyx()

            # Header
            num_entries = sum(1 for d in self.logs if d.year == self.current_year)
            hdr = f"Today is: {datetime.date.today().strftime('%d. %m. %Y.')}  | There are {num_entries} log entries for year {self.current_year}."
            stdscr.addstr(0, max(0, (width - len(hdr)) // 2), hdr, curses.A_BOLD)

            sorted_secs = sorted(self.all_sections.keys())
            sec_list = ["<select none>"] + [f"{self.all_sections[s]:4} | {s}" for s in sorted_secs]
            cur_sec = None if sel_sec == 0 else sorted_secs[sel_sec-1]

            if cur_sec: available_tags = sorted(list(self.section_to_tags.get(cur_sec, set())))
            else: available_tags = sorted(self.all_tags.keys())
            tag_list = ["<select none>"] + [f"{self.all_tags[t]:4} | {t}" for t in available_tags]
            cur_tag = None if sel_tag == 0 else available_tags[sel_tag-1]

            # Layout: Menus
            menu_w = 24
            self.draw_box(stdscr, 1, 0, 18, menu_w, "Sections", focus == 0)
            for i, line in enumerate(sec_list[:16]):
                style = curses.A_REVERSE if focus == 0 and i == sel_sec else 0
                stdscr.addstr(2+i, 1, line[:menu_w-2].ljust(menu_w-2), style)

            self.draw_box(stdscr, 1, menu_w, 18, menu_w, "Tags", focus == 1)
            for i, line in enumerate(tag_list[:16]):
                style = curses.A_REVERSE if focus == 1 and i == sel_tag else 0
                stdscr.addstr(2+i, menu_w+1, line[:menu_w-2].ljust(menu_w-2), style)

            # Calendar
            cal_x = menu_w * 2
            cal_w = width - cal_x
            self.draw_box(stdscr, 1, cal_x, 18, cal_w, str(self.current_year), focus == 2)

            # Simple calendar grid
            for m in range(1, 13):
                row, col = (m-1)//3, (m-1)%3
                mx = cal_x + 1 + col * 22
                my = 2 + row * 4 # Simplified
                # ... draw month ... (just a placeholder for now)

            # Preview
            prev_y = 19
            self.draw_box(stdscr, prev_y, 0, height - prev_y, width, f"log preview for {self.selected_date.strftime('%d. %m. %y.')}")
            if self.selected_date in self.logs:
                lines = self.logs[self.selected_date].splitlines()
                for i, line in enumerate(lines[:height - prev_y - 2]):
                    stdscr.addstr(prev_y + 1 + i, 1, line[:width-2])

            stdscr.refresh()
            ch = stdscr.getch()
            if ch == ord('q'): break
            elif ch == 9: focus = (focus + 1) % 3
            elif ch == curses.KEY_BTAB: focus = (focus - 1) % 3
            elif ch == ord('s'): # Scratchpad view
                pass # TODO
            elif ch == ord('+'):
                self.current_year += 1
                self.update_counts()
            elif ch == ord('-'):
                self.current_year -= 1
                self.update_counts()
            elif focus == 0:
                if ch == curses.KEY_UP or ch == ord('k'): sel_sec = max(0, sel_sec - 1)
                elif ch == curses.KEY_DOWN or ch == ord('j'): sel_sec = min(len(sec_list)-1, sel_sec + 1)
            elif focus == 1:
                if ch == curses.KEY_UP or ch == ord('k'): sel_tag = max(0, sel_tag - 1)
                elif ch == curses.KEY_DOWN or ch == ord('j'): sel_tag = min(len(tag_list)-1, sel_tag + 1)
            elif focus == 2:
                # Calendar navigation
                if ch == curses.KEY_LEFT or ch == ord('h'): self.selected_date -= datetime.timedelta(days=1)
                elif ch == curses.KEY_RIGHT or ch == ord('l'): self.selected_date += datetime.timedelta(days=1)
                elif ch == curses.KEY_UP or ch == ord('k'): self.selected_date -= datetime.timedelta(days=7)
                elif ch == curses.KEY_DOWN or ch == ord('j'): self.selected_date += datetime.timedelta(days=7)
                self.current_year = self.selected_date.year

    def run(self): curses.wrapper(self.main_loop)

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("-c", "--config", default=str(get_default_config_path()))
    parser.add_argument("--log-dir-path")
    parser.add_argument("--log-name-format")
    parser.add_argument("--sunday-start", action="store_true")
    parser.add_argument("--first-line-section", action="store_true")
    parser.add_argument("--password")
    args = parser.parse_args()
    App(args).run()
